pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        vm.prank(address(this), address(this));
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 a) internal {
        vm.assume(true);
        try c.AdjustDifficulty(a) {} catch { return; }
        assertTrue(c.currentDifficulty() == a);
    }

    function testFuzz_run(uint256 a) public {
        _run(a);
    }

    receive() external payable {}
}
